  - {id: crack_jet,      unit: usd_bbl, reference: 23,   start: 55,  additive: true, volatility: 10, reversion: 1.5, inflate: false, stream: sea, correlated_with: crude_oil, correlation: 0.5, src: "GDD 23 (P-16)", assumption_fields: [volatility, reversion, correlation]}
