  - {id: freight_china_sa_west, unit: usd_feu, reference: 3600, start: 6725, volatility: 0.45, reversion: 1.5, inflate: true, stream: sea, correlated_with: freight_china_us_west, correlation: 0.8, src: "GDD 17 lanes (P-15)", assumption_fields: [reference, volatility, reversion, correlation]}
